<script setup>
import{onMounted,ref}from'vue';import{api}from'../../api/http.js';import{sessionStore}from'../../stores/session.js';import T from'../../components/common/WorkspaceTable.vue';import PageHeader from'../../components/common/PageHeader.vue';const rows=ref([]),error=ref(''),form=ref({employee_code:'',name:'',email:'',phone:'',position:'',department:'',status:'active',pay_type:'monthly',basic_salary:0,hourly_rate:0,leave_balance:15});async function load(){try{error.value='';const d=await api.employees({per_page:100});rows.value=d.data||[]}catch(e){error.value=e.message}}async function save(){try{error.value='';await api.post('/employees',form.value);await load()}catch(e){error.value=e.message}}onMounted(load)
</script><template><PageHeader title="Employees" description="Create and review employee records."/><p v-if="error" class="form-error">{{error}}</p><form v-if="sessionStore.can('hr.employees.edit')" class="inline-form" @submit.prevent="save"><input v-model="form.employee_code" placeholder="Employee no." required><input v-model="form.name" placeholder="Full name" required><input v-model="form.department" placeholder="Department"><input v-model="form.position" placeholder="Position"><select v-model="form.pay_type"><option value="monthly">Monthly</option><option value="hourly">Hourly</option></select><button class="primary-button">Add employee</button></form><T :columns="[{key:'employee_no',label:'Employee No.'},{key:'full_name',label:'Name'},{key:'department',label:'Department'},{key:'position',label:'Position'},{key:'employment_status',label:'Status'},{key:'pay_type',label:'Pay Type'}]" :rows="rows"/></template>
